129 | static int draw_executor_stream(AwtsBrowserState* state) {
130 |   const char* stream = AWTS_NATIVE_RENDER_STREAM;
131 |   if (!stream || !*stream) return 0;
132 |   char* copy = _strdup(stream);
133 |   if (!copy) return 0;
134 |   float ox = sx(state, 96), oy = sy(state, 150);
135 |   float scaleX = sw(state, 2), scaleY = -sh(state, 2);
136 |   for (char* line = copy; line && *line;) {
137 |     char* next = strchr(line, '\n');
138 |     if (next) *next++ = 0;
139 |     char kind[16], id[16], a[64], b[64], c[160], d[64], e[64];
140 |     char* at = line;
141 |     memset(kind, 0, sizeof(kind)); memset(id, 0, sizeof(id));
142 |     memset(a, 0, sizeof(a)); memset(b, 0, sizeof(b)); memset(c, 0, sizeof(c));
143 |     memset(d, 0, sizeof(d)); memset(e, 0, sizeof(e));
144 |     next_part(&at, kind, sizeof(kind)); next_part(&at, id, sizeof(id));
145 |     next_part(&at, a, sizeof(a)); next_part(&at, b, sizeof(b));
146 |     next_part(&at, c, sizeof(c)); next_part(&at, d, sizeof(d)); next_part(&at, e, sizeof(e));
147 |     if (!strcmp(kind, "BOX")) {
148 |       float r, g, blue; hex_color(e, &r, &g, &blue);
149 |       rect(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, r, g, blue);
150 |       outline(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, 0.70f, 0.72f, 0.78f);
151 |     } else if (!strcmp(kind, "TEXT")) {
152 |       float r, g, blue; hex_color(d, &r, &g, &blue);
153 |       awts_draw_text(state, ox + atof(a) * scaleX, oy + atof(b) * scaleY, c, r, g, blue);
154 |     } else if (!strcmp(kind, "WEBGL")) {
155 |       rect(sx(state, 470), sy(state, 180 + atoi(id) * 18), sw(state, 220), -sh(state, 10), 0.10f, 0.18f, 0.32f);
156 |     }
157 |     line = next;
158 |   }
159 |   free(copy);
160 |   return 1;
161 | }
